            HistoricalArticle(slug="mughal-princely-courts-transformation", title="Mughal & Princely Courts: Rhythmic Virtuosity & Refinement", era="Court Patronage Era", period_label="16th Century – 19th Century CE", timeline_order=2, summary="As Kathak entered Mughal and Rajput royal courts, it evolved from devotional temple narrative into a sophisticated chamber art emphasizing intricate footwork, chakkars, and rhythmic dialogue.", content="From the 16th century onward, Kathak received sustained patronage in Mughal imperial courts as well as Hindu Rajput courts in Rajasthan and regional courts such as Awadh (Lucknow) and Raigarh.", key_milestones=json.dumps(["Transition from open temple courtyards to intimate royal mehfils", "Integration of Thumri, Dadra, and Tarana", "Patronage of Nawab Wajid Ali Shah and Maharaja Chakradhar Singh"]), image_url="https://images.unsplash.com/photo-1524492412937-b28074a5d7da?auto=format&fit=crop&w=1200&q=80", image_credit="Historic North Indian palace courtyard architecture (Unsplash)"),
            HistoricalArticle(slug="twentieth-century-revival-institutionalisation", title="20th-Century Revival, Pedagogy & Modern Proscenium Stage", era="Modern Revival & Institutionalisation", period_label="20th Century CE", timeline_order=3, summary="Pioneering dancers, gurus, and post-independence cultural institutions brought Kathak from private salons to national proscenium stages and structured university curricula.", content="In the early-to-mid 20th century, pioneers such as Madame Menaka (Leila Sokhey) and visionary gurus revitalised Kathak's public stature. Following independence, Sangeet Natak Akademi and Kathak Kendra formalised curricula.", key_milestones=json.dumps(["Madame Menaka's international tours in the 1930s", "Recognition by Sangeet Natak Akademi and founding of Kathak Kendra", "Development of structured syllabi and ensemble choreography"]), image_url="https://images.unsplash.com/photo-1514525253161-7a46d19cd819?auto=format&fit=crop&w=1200&q=80", image_credit="Classical concert stage lighting (Unsplash)"),
            HistoricalArticle(slug="kathak-in-contemporary-india-world", title="Kathak in Contemporary India & Global Practice", era="Contemporary Practice", period_label="21st Century CE", timeline_order=4, summary="Today, Kathak thrives across solo traditional recitals, cross-disciplinary collaborations, academic scholarship, and digital archives.", content="In contemporary India and across the global diaspora, Kathak practitioners balance rigorous adherence to traditional solo format with innovative thematic choreography and digital archiving.", key_milestones=json.dumps(["Coexistence of solo mehfil recitals and ensemble productions", "Accredited university degree programs", "Digital archives and open pedagogical documentation"]), image_url="https://images.unsplash.com/photo-1547153760-18fc86324498?auto=format&fit=crop&w=1200&q=80", image_credit="Classical dance movement study (Unsplash)"),
