            Gharana(slug="banaras-gharana", name="Banaras Gharana", hindi_name="बनारस घराना", origin_region="Varanasi (Banaras), Uttar Pradesh", founder_or_pioneers="Janaki Prasad, Dulha Ram, Ganeshilal, Hanuman Prasad, Gopalji, Sitara Devi", historical_background="Founded by Janaki Prasad who settled in Varanasi, absorbing the spiritual vitality, temple rituals, and tabla-pakhawaj traditions of Kashi.", stylistic_characteristics="Distinguished by distinctive floorwork, crisp heel-centric footwork (edhi ka kaam), symmetry of body angles, and use of natwari bols.", rhythm_and_movement_notes="Features characteristic syllabic patterns ('thun thun', 'tat tat', 'dig dig') and brisk chakkars on both right and left sides.", performance_traditions="Strong integration of Shiv Tandava, Holi Dhamar, Chaiti, Kajri, and devotional compositions of Varanasi.", notable_contributions="Distinctive natwari bol vocabulary and charismatic solo stage presentation.", prominent_exponents="Pandit Janaki Prasad, Pandit Sukhdev Maharaj, Vidushi Sitara Devi, Guru Gopi Krishna, Pandit Ravi Shankar Mishra, Pandit Mata Prasad Mishra", cultural_nuance_note="Shares historical roots with Rajasthan through Janaki Prasad while developing an unmistakable Kashi aesthetic.", image_url="https://images.unsplash.com/photo-1561361513-2d000a50f0dc?auto=format&fit=crop&w=1200&q=80", image_credit="Ghats of Varanasi along the Ganga (Unsplash)"),
            Gharana(slug="raigarh-gharana", name="Raigarh Gharana", hindi_name="रायगढ़ घराना", origin_region="Raigarh, Chhattisgarh", founder_or_pioneers="Maharaja Chakradhar Singh (with resident maestros Pandit Jailal, Pandit Acchan Maharaj, Pandit Kartik Ram, Pandit Kalyan Das)", historical_background="Established in the early 20th century under the scholarly patronage of Maharaja Chakradhar Singh (1905–1947), bringing together masters of Lucknow and Jaipur.", stylistic_characteristics="Combines lyrical abhinaya of Lucknow with rhythmic precision of Jaipur, enriched by original compositions documented in 'Nartan Sarvaswam'.", rhythm_and_movement_notes="Notable for unique poetic parans, rare taal structures, and nature-inspired rhythmic syllables.", performance_traditions="Performs signature Raigarh compositions including 'Kachhuwa Paran', 'Mayur Paran', and 'Badal Paran'.", notable_contributions="Systematic written notation and archiving of hundreds of Kathak and percussion compositions.", prominent_exponents="Maharaja Chakradhar Singh, Pandit Kartik Ram, Pandit Kalyan Das Mahant, Pandit Phirtu Maharaj, Pandit Ramlal Bareth", cultural_nuance_note="Represents both a stylistic synthesis and one of the earliest systematic documentation efforts in Kathak history.", image_url="https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?auto=format&fit=crop&w=1200&q=80", image_credit="Classical Indian cultural heritage motif (Unsplash)"),
